def modular_sum(arr, n, m):
    """Check whether a nonempty subset of the first n values sums to 0 modulo m."""
    if m == 0:
        raise ValueError("m must be nonzero")
    if not 0 <= n <= len(arr):
        raise ValueError("n must be between 0 and len(arr)")

    m = abs(m)
    if n >= m:
        return True  # Two of the n + 1 prefix sums have the same remainder.

    reachable = set()
    for i in range(n):
        r = arr[i] % m
        if r == 0 or (-r) % m in reachable:
            return True
        additions = {(s + r) % m for s in reachable}
        reachable.update(additions)
        reachable.add(r)
    return False
```

