def count_Pairs(values, n=None):
    if n is None:
        n = len(values)
    if not 0 <= n <= len(values):
        raise ValueError("n must be between 0 and the length of values")

    seen = {}
    pairs = 0
    for i in range(n):
        value = values[i]
        equal = seen.get(value, 0)
        pairs += i - equal
        seen[value] = equal + 1
    return pairs
