from collections import Counter
from math import gcd

def main():
    n = int(sys.stdin.buffer.readline())
    counts = Counter(map(int, sys.stdin.buffer.read().split()))
    result = []

    for x in sorted(counts, reverse=True):
        while counts[x] > 0:
            counts[x] -= 1
            for y in result:
                counts[gcd(x, y)] -= 2
            result.append(x)
        if len(result) == n:
            break

    print(*result)

if __name__ == "__main__":
    main()
