import sys

def main():
    n, *cups = map(int, sys.stdin.buffer.read().split())
    level, remainder = divmod(sum(cups), n)
    if remainder:
        print("Unrecoverable configuration.")
        return

    low = [i for i, volume in enumerate(cups, 1) if volume < level]
    high = [i for i, volume in enumerate(cups, 1) if volume > level]

    if not low and not high:
        print("Exemplary pages.")
    elif len(low) == len(high) == 1:
        amount = level - cups[low[0] - 1]
        print(f"{amount} ml. from cup #{low[0]} to cup #{high[0]}.")
    else:
        print("Unrecoverable configuration.")

if __name__ == "__main__":
    main()
